#include <stdint.h>

/*
 * Conceptual PoC demonstrating the integer overflow vulnerability
 * in libavcodec/h264_slice.c. The expression '16 * 6 * alloc_size'
 * is evaluated as a 32-bit signed int before being cast to size_t.
 * Large alloc_size values cause the multiplication to wrap around
 * to a small positive value, leading to an undersized allocation.
 */
void demonstrate_overflow(int alloc_size) {
    // Vulnerable: 16 and 6 are int literals, so arithmetic is 32-bit signed
    size_t wrapped_size = (size_t)(16 * 6 * alloc_size);

    // Expected size if calculated correctly in 64-bit
    size_t expected_size = (size_t)16 * 6 * (size_t)alloc_size;

    printf("Input alloc_size: %d\n", alloc_size);
    printf("Vulnerable calc (wrapped): %zu\n", wrapped_size);
    printf("Expected/Safe calc: %zu\n", expected_size);

    // Allocate based on the wrapped-around size
    void *buf = malloc(wrapped_size);
    if (!buf) return;

    // Simulate decoder writing to the buffer assuming expected_size
    // In a real scenario, this write exceeds the allocated buffer bounds
    printf("Exploit: Allocating %zu bytes but decoder writes up to %zu bytes.\n", wrapped_size, expected_size);
    printf("Result: Heap buffer overflow when write exceeds %zu bytes.\n", wrapped_size);

    free(buf);
}

int main() {
    // 96 * alloc_size > INT32_MAX (2147483647)
    // Triggers 32-bit signed integer overflow/wrap-around
    int malicious_value = 22369622;
    demonstrate_overflow(malicious_value);
    return 0;
}

