// Simulates the vulnerable allocation size calculation
size_t calculate_alloc_size(int32_t alloc_size) {
    // Vulnerability: This multiplication is performed using 32-bit signed arithmetic
    // before being implicitly cast to size_t (unsigned 64-bit on most systems).
    // If alloc_size is large enough, the result wraps around (integer overflow).
    int32_t wrapped_size = alloc_size * 2 * 21;
    return (size_t)wrapped_size; // Cast to size_t after overflow has already occurred
}

