    // A carefully chosen alloc_size that causes the 32-bit signed multiplication
    // to wrap around to a small positive value (80 bytes)
    int32_t large_alloc_size = 102261128;

    // Calculate the intended size vs actual allocated size
    size_t intended_size = (size_t)large_alloc_size * 2 * 21;
    size_t actual_alloc_size = calculate_alloc_size(large_alloc_size);

    printf("Intended allocation size: %zu\n", intended_size);
    printf("Actual allocation size (after overflow): %zu\n", actual_alloc_size);

    // Simulate allocation with the undersized buffer
    // In reality, av_fast_malloc would allocate 'actual_alloc_size' bytes
