/*
 * Minimal PoC demonstrating signed integer overflow in dimension/block count calculations.
 * Maps to the vulnerability in libavcodec/hevcdec.c where malformed width/height or
 * log2_min_cb_size triggers overflow in expressions like:
 *   int pic_size_in_ctb = ((width >> log2_min_cb_size) + 1) * height;
 *   int ctb_count = sps->ctb_width * sps->ctb_height;
 */
void simulate_vulnerable_calculation(int width, int height, int log2_min_cb_size) {
    // Step 1: Malformed or extreme inputs cause signed 32-bit overflow
    // When log2_min_cb_size is 0 and width/height are large, the shift/multiply wraps.
    int pic_size_in_ctb = ((width >> log2_min_cb_size) + 1) * height;
    int ctb_count = width * height;

    printf("[+] Raw calculation results (int32_t):\n");
    printf("    pic_size_in_ctb = %d\n", pic_size_in_ctb);
    printf("    ctb_count       = %d\n", ctb_count);

    // Step 2: Allocation context triggers C usual arithmetic conversions
    // When the negative int is multiplied by sizeof(element) or passed to a function
    // expecting size_t, it is sign-extended to a massive unsigned value.
    size_t requested_alloc = (size_t)pic_size_in_ctb * sizeof(int);
    printf("[+] Converted to size_t for allocation: %zu bytes\n", requested_alloc);

    // Step 3: Downstream usage of the original overflowed int as index/loop bound
    // The negative value bypasses unsigned checks and causes out-of-bounds access.
    int loop_idx = pic_size_in_ctb;
    printf("[+] Using overflowed int as loop bound/index: %d\n", loop_idx);
    printf("    (In real code, this would trigger OOB read/write)\n");
}

int main(void) {
    // Malformed parameters that trigger the overflow
    int width  = 1 << 16;  // 65536
    int height = 1 << 16;  // 65536
    int log2_min_cb_size = 0; // Malformed/missing shift amount

    printf("=== Signed Integer Overflow PoC ===\n");
    simulate_vulnerable_calculation(width, height, log2_min_cb_size);
    return 0;
}

